import * as T from './vendor/three.module.js';
export function createEquipmentSurface(source){
 source.updateWorldMatrix(true,true);const inverse=source.matrixWorld.clone().invert(),vertices=[];source.traverse(mesh=>{if(!mesh.isMesh)return;const p=mesh.geometry.attributes.position,matrix=inverse.clone().multiply(mesh.matrixWorld);for(let i=0;i<p.count;i++)vertices.push(new T.Vector3().fromBufferAttribute(p,i).applyMatrix4(matrix));});
 return {minimumY(matrix){const e=matrix.elements;let y=Infinity;for(const v of vertices)y=Math.min(y,v.x*e[1]+v.y*e[5]+v.z*e[9]+e[13]);return y;}};
}
// A rigid cosmetic copy. Geometry/textures remain with the source owner.
export function createCasualtyEquipmentVisual(source){
 const root=new T.Group(),visual=source.clone(true),materials=new Map(),vertices=[],bounds=new T.Box3();root.add(visual);root.visible=false;visual.position.set(0,0,0);visual.quaternion.identity();visual.scale.set(1,1,1);visual.visible=true;visual.updateMatrixWorld(true);
 visual.traverse(mesh=>{if(!mesh.isMesh)return;if(mesh.isSkinnedMesh)throw Error('Casualty equipment requires a rigid model');const p=mesh.geometry.attributes.position;for(let i=0;i<p.count;i++){const v=new T.Vector3().fromBufferAttribute(p,i).applyMatrix4(mesh.matrixWorld);vertices.push(v);bounds.expandByPoint(v);}const clone=original=>{if(!materials.has(original)){const material=original.clone();material.onBeforeCompile=original.onBeforeCompile;material.customProgramCacheKey=original.customProgramCacheKey;materials.set(original,{material,opacity:original.opacity,transparent:original.transparent,depthWrite:original.depthWrite});}return materials.get(original).material;};mesh.material=Array.isArray(mesh.material)?mesh.material.map(clone):clone(mesh.material);mesh.castShadow=mesh.receiveShadow=false;mesh.raycast=()=>{};});
 if(!vertices.length)throw Error('Casualty equipment requires visible geometry');const center=bounds.getCenter(new T.Vector3());for(const v of vertices)v.sub(center);visual.position.copy(center).negate();let disposed=false;
 return {root,visual,center,vertices,setOpacity(opacity){for(const {material,opacity:base,transparent,depthWrite}of materials.values()){const blend=opacity<1,changed=material.transparent!==(blend||transparent);material.opacity=base*opacity;material.transparent=blend||transparent;material.depthWrite=blend?false:depthWrite;if(changed)material.needsUpdate=true;}},place(matrix){matrix.decompose(root.position,root.quaternion,root.scale);root.position.copy(center).applyMatrix4(matrix);root.updateMatrixWorld(true);},minimumY(matrix){const e=matrix.elements;let y=Infinity;for(const v of vertices)y=Math.min(y,(v.x+center.x)*e[1]+(v.y+center.y)*e[5]+(v.z+center.z)*e[9]+e[13]);return y;},dispose(){if(disposed)return;disposed=true;root.removeFromParent();root.visible=false;for(const {material}of materials.values())material.dispose();materials.clear();}};
}
